def workflow_stop(obj, names):
    """ Stop one or more running workflows.

    \b
    NAMES: The names, ids or job ids of the workflows that should be stopped.
           Leave empty to stop all running workflows.
    """
        from aiida.cmdline.utils import echo
        from aiida.cmdline.commands.cmd_work import cmd_work

        if not names:
            echo.echo_success('Stopping all running workflows')
            return cmd_work.workflow_stop(obj, [])

        for name in names:
            if not name.isdigit():
                echo.echo_warning(f'Workflow {name} is not an integer, skipping')
                continue

            try:
                echo.echo_info(f'Stopping workflow {name}')
                obj.stop(int(name))
            except ValueError:
                echo.echo_warning(f'Workflow {name} is not a valid integer, skipping')


